// handleWsRequest handles ws operation.
//
// # WebSocketプロトコル
// ## 送信
// `コマンド:引数1:引数2:...
// `のような形式のTextMessageをサーバーに送信することで、このWebSocketセッションに対する設定が実行できる。
// ### `viewstate`コマンド
// このWebSocketセッションが見ているチャンネル(イベントを受け取るチャンネル)を設定する。
// 現時点では1つのセッションに対して1つのチャンネルしか設定できない。
// `viewstate:{チャンネルID}:{閲覧状態}`
// + チャンネルID: 対象のチャンネルID
// + 閲覧状態: `none`, `monitoring`, `editing`
// 最初の`viewstate`コマンドを送る前、または`viewstate:null`,
// `viewstate:`を送信した後は、このセッションはどこのチャンネルも見ていないことになる。
// ### `rtcstate`コマンド
// 自分のWebRTC状態を変更する。
// 他のコネクションが既に状態を保持している場合、変更することができません。
// `rtcstate:{チャンネルID}:({状態}:{セッションID})*`
// コネクションが切断された場合、自分のWebRTC状態はリセットされます。
// ### `timeline_streaming`コマンド
// 全てのパブリックチャンネルの`MESSAGE_CREATED`イベントを受け取るかどうかを設定する。
// 初期状態は`off`です。
// `timeline_streaming:(on|off|true|false)`
// ## 受信
// TextMessageとして各種イベントが`type`と`body`を持つJSONとして非同期に送られます。
// 例:
// ```json
// {"type":"USER_ONLINE","body":{"id":"7dd8e07f-7f5d-4331-9176-b56a4299768b"}}
// ```
// ## イベント一覧
// ### `USER_JOINED`
// ユーザーが新規登録された。
// 対象: 全員
// + `id`: 登録されたユーザーのId
// ### `USER_UPDATED`
// ユーザーの情報が更新された。
// 対象: 全員
// + `id`: 情報が更新されたユーザーのId
// ### `USER_TAGS_UPDATED`
// ユーザーのタグが更新された。
// 対象: 全員
// + `id`: タグが更新されたユーザーのId
// + `tag_id`: 更新されたタグのId
// ### `USER_ICON_UPDATED`
// ユーザーのアイコンが更新された。
// 対象: 全員
// + `id`: アイコンが更新されたユーザーのId
// ### `USER_WEBRTC_STATE_CHANGED`
// ユーザーのWebRTCの状態が変化した
// 対象: 全員
// + `user_id`: 変更があったユーザーのId
// + `channel_id`: ユーザーの変更後の接続チャンネルのId
// + `sessions`: ユーザーの変更後の状態(配列)
// + `state`: 状態
// + `sessionId`: セッションID
// ### `USER_VIEWSTATE_CHANGED`
// ユーザーのチャンネルの閲覧状態が変化した
// 対象: 変化したWSセッションを含めた、該当ユーザーのWSセッション全て
// + `view_states`:
// 変化したWSセッションを含めた、該当ユーザーの変更後の状態(配列)
// + `key`: WSセッションの識別子
// + `channel_id`: 閲覧しているチャンネルId
// + `state`: 閲覧状態
// ### `USER_ONLINE`
// ユーザーがオンラインになった。
// 対象: 全員
// + `id`: オンラインになったユーザーのId
// ### `USER_OFFLINE`
// ユーザーがオフラインになった。
// 対象: 全員
// + `id`: オフラインになったユーザーのId
// ### `USER_GROUP_CREATED`
// ユーザーグループが作成された
// 対象: 全員
// + `id`: 作成されたユーザーグループのId
// ### `USER_GROUP_UPDATED`
// ユーザーグループが更新された
// 対象: 全員
// + `id`: 作成されたユーザーグループのId
// ### `USER_GROUP_DELETED`
// ユーザーグループが削除された
// 対象: 全員
// + `id`: 削除されたユーザーグループのId
// ### `CHANNEL_CREATED`
// チャンネルが新規作成された。
// 対象: 該当チャンネルを閲覧可能な全員
// + `id`: 作成されたチャンネルのId
// + `dm_user_id`: (DMの場合のみ) DM相手のユーザーId
// ### `CHANNEL_UPDATED`
// チャンネルの情報が変更された。
// 対象: 該当チャンネルを閲覧可能な全員
// + `id`: 変更があったチャンネルのId
// + `dm_user_id`: (DMの場合のみ) DM相手のユーザーId
// ### `CHANNEL_DELETED`
// チャンネルが削除された。
// 対象: 該当チャンネルを閲覧可能な全員
// + `id`: 削除されたチャンネルのId
// + `dm_user_id`: (DMの場合のみ) DM相手のユーザーId
// ### `CHANNEL_STARED`
// 自分がチャンネルをスターした。
// 対象: 自分
// + `id`: スターしたチャンネルのId
// ### `CHANNEL_UNSTARED`
// 自分がチャンネルのスターを解除した。
// 対象: 自分
// + `id`: スターしたチャンネルのId
// ### `CHANNEL_VIEWERS_CHANGED`
// チャンネルの閲覧者が変化した。
// 対象: 該当チャンネルを閲覧しているユーザー
// + `id`: 変化したチャンネルのId
// + `viewers`: 変化後の閲覧者(配列)
// + `userId`: ユーザーId
// + `state`: 閲覧状態
// + `updatedAt`: 閲覧状態の更新日時
// ### `CHANNEL_SUBSCRIBERS_CHANGED`
// チャンネルの購読者が変化した。
// 対象: 該当チャンネルを閲覧しているユーザー
// + `id`: 変化したチャンネルのId
// ### `MESSAGE_CREATED`
// メッセージが投稿された。
// 対象:
// 投稿チャンネルを閲覧しているユーザー・投稿チャンネルに通知をつけているユーザー・メンションを受けたユーザー
// + `id`: 投稿されたメッセージのId
// + `is_citing`:
// 投稿されたメッセージがWebSocketを接続しているユーザーの投稿を引用しているかどうか
// ### `MESSAGE_UPDATED`
// メッセージが更新された。
// 対象: 投稿チャンネルを閲覧しているユーザー
// + `id`: 更新されたメッセージのId
// ### `MESSAGE_DELETED`
// メッセージが削除された。
// 対象: 投稿チャンネルを閲覧しているユーザー
// + `id`: 削除されたメッセージのId
// ### `MESSAGE_STAMPED`
// メッセージにスタンプが押された。
// 対象: 投稿チャンネルを閲覧しているユーザー
// + `message_id`: メッセージId
// + `user_id`: スタンプを押したユーザーのId
// + `stamp_id`: スタンプのId
// + `count`: そのユーザーが押した数
// + `created_at`:
// そのユーザーがそのスタンプをそのメッセージに最初に押した日時
// ### `MESSAGE_UNSTAMPED`
// メッセージからスタンプが外された。
// 対象: 投稿チャンネルを閲覧しているユーザー
// + `message_id`: メッセージId
// + `user_id`: スタンプを押したユーザーのId
// + `stamp_id`: スタンプのId
// ### `MESSAGE_PINNED`
// メッセージがピン留めされた。
// 対象: 投稿チャンネルを閲覧しているユーザー
// + `message_id`: ピンされたメッセージのID
// + `channel_id`: ピンされたメッセージのチャンネルID
// ### `MESSAGE_UNPINNED`
// ピン留めされたメッセージのピンが外された。
// 対象: 投稿チャンネルを閲覧しているユーザー
// + `message_id`: ピンが外されたメッセージのID
// + `channel_id`: ピンが外されたメッセージのチャンネルID
// ### `MESSAGE_READ`
// 自分があるチャンネルのメッセージを読んだ。
// 対象: 自分
// + `id`: 読んだチャンネルId
// ### `STAMP_CREATED`
// スタンプが新しく追加された。
// 対象: 全員
// + `id`: 作成されたスタンプのId
// ### `STAMP_UPDATED`
// スタンプが修正された。
// 対象: 全員
// + `id`: 修正されたスタンプのId
// ### `STAMP_DELETED`
// スタンプが削除された。
// 対象: 全員
// + `id`: 削除されたスタンプのId
// ### `STAMP_PALETTE_CREATED`
// スタンプパレットが新しく追加された。
// 対象: 自分
// + `id`: 作成されたスタンプパレットのId
// ### `STAMP_PALETTE_UPDATED`
// スタンプパレットが修正された。
// 対象: 自分
// + `id`: 修正されたスタンプパレットのId
// ### `STAMP_PALETTE_DELETED`
// スタンプパレットが削除された。
// 対象: 自分
// + `id`: 削除されたスタンプパレットのId
// ### `CLIP_FOLDER_CREATED`
// クリップフォルダーが作成された。
// 対象：自分
// + `id`: 作成されたクリップフォルダーのId
// ### `CLIP_FOLDER_UPDATED`
// クリップフォルダーが修正された。
// 対象: 自分
// + `id`: 更新されたクリップフォルダーのId
// ### `CLIP_FOLDER_DELETED`
// クリップフォルダーが削除された。
// 対象: 自分
// + `id`: 削除されたクリップフォルダーのId
// ### `CLIP_FOLDER_MESSAGE_DELETED`
// クリップフォルダーからメッセージが除外された。
// 対象: 自分
// + `folder_id`: メッセージが除外されたクリップフォルダーのId
// + `message_id`: クリップフォルダーから除外されたメッセージのId
// ### `CLIP_FOLDER_MESSAGE_ADDED`
// クリップフォルダーにメッセージが追加された。
// 対象: 自分
// + `folder_id`: メッセージが追加されたクリップフォルダーのId
// + `message_id`: クリップフォルダーに追加されたメッセージのId.
//
// GET /ws
func (s *Server) handleWsRequest(args [0]string, argsEscaped bool, w http.ResponseWriter, r *http.Request) {
	otelAttrs := []attribute.KeyValue{
		otelogen.OperationID("ws"),
		semconv.HTTPRequestMethodKey.String("GET"),
		semconv.HTTPRouteKey.String("/ws"),
	}

	// Start a span for this request.
	ctx, span := s.cfg.Tracer.Start(r.Context(), "Ws",
		trace.WithAttributes(otelAttrs...),
		serverSpanKind,
	)
	defer span.End()

	// Add Labeler to context.
	labeler := &Labeler{attrs: otelAttrs}
	ctx = contextWithLabeler(ctx, labeler)

	// Run stopwatch.
	startTime := time.Now()
	defer func() {
		elapsedDuration := time.Since(startTime)
		attrOpt := metric.WithAttributeSet(labeler.AttributeSet())

		// Increment request counter.
		s.requests.Add(ctx, 1, attrOpt)

		// Use floating point division here for higher precision (instead of Millisecond method).
		s.duration.Record(ctx, float64(float64(elapsedDuration)/float64(time.Millisecond)), attrOpt)
	}()

	var (
		recordError = func(stage string, err error) {
			span.RecordError(err)
			span.SetStatus(codes.Error, stage)
			s.errors.Add(ctx, 1, metric.WithAttributeSet(labeler.AttributeSet()))
		}
		err          error
		opErrContext = ogenerrors.OperationContext{
			Name: "Ws",
			ID:   "ws",
		}
	)
	{
		type bitset = [1]uint8
		var satisfied bitset
		{
			sctx, ok, err := s.securityOAuth2(ctx, "Ws", r)
			if err != nil {
				err = &ogenerrors.SecurityError{
					OperationContext: opErrContext,
					Security:         "OAuth2",
					Err:              err,
				}
				defer recordError("Security:OAuth2", err)
				s.cfg.ErrorHandler(ctx, w, r, err)
				return
			}
			if ok {
				satisfied[0] |= 1 << 0
				ctx = sctx
			}
		}
		{
			sctx, ok, err := s.securityBearerAuth(ctx, "Ws", r)
			if err != nil {
				err = &ogenerrors.SecurityError{
					OperationContext: opErrContext,
					Security:         "BearerAuth",
					Err:              err,
				}
				defer recordError("Security:BearerAuth", err)
				s.cfg.ErrorHandler(ctx, w, r, err)
				return
			}
			if ok {
				satisfied[0] |= 1 << 1
				ctx = sctx
			}
		}

		if ok := func() bool {
		nextRequirement:
			for _, requirement := range []bitset{
				{0b00000001},
				{0b00000010},
			} {
				for i, mask := range requirement {
					if satisfied[i]&mask != mask {
						continue nextRequirement
					}
				}
				return true
			}
			return false
		}(); !ok {
			err = &ogenerrors.SecurityError{
				OperationContext: opErrContext,
				Err:              ogenerrors.ErrSecurityRequirementIsNotSatisfied,
			}
			defer recordError("Security", err)
			s.cfg.ErrorHandler(ctx, w, r, err)
			return
		}
	}

	var response *WsSwitchingProtocols
	if m := s.cfg.Middleware; m != nil {
		mreq := middleware.Request{
			Context:          ctx,
			OperationName:    "Ws",
			OperationSummary: "WebSocket通知ストリームに接続します",
			OperationID:      "ws",
			Body:             nil,
			Params:           middleware.Parameters{},
			Raw:              r,
		}

		type (
			Request  = struct{}
			Params   = struct{}
			Response = *WsSwitchingProtocols
		)
		response, err = middleware.HookMiddleware[
			Request,
			Params,
			Response,
		](
			m,
			mreq,
			nil,
			func(ctx context.Context, request Request, params Params) (response Response, err error) {
				err = s.h.Ws(ctx)
				return response, err
			},
		)
	} else {
		err = s.h.Ws(ctx)
	}
	if err != nil {
		defer recordError("Internal", err)
		s.cfg.ErrorHandler(ctx, w, r, err)
		return
	}

	if err := encodeWsResponse(response, w, span); err != nil {
		defer recordError("EncodeResponse", err)
		if !errors.Is(err, ht.ErrInternalServerErrorResponse) {
			s.cfg.ErrorHandler(ctx, w, r, err)
		}
		return
	}
}
